using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "MadnessSurgeCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/MadnessSurgeCustomDescription", order = 0)]
public class MadnessSurgeCustomDescription : WhereXTimesCustomDescription
{
	[SerializeField]
	private DiceTier hexDiceTier;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		MadnessSurgeAction madnessSurgeAction = battleAction as MadnessSurgeAction;
		return GetActionDescription(amountModified, battleAction, madnessSurgeAction.CorruptAction);
	}

	protected override string GetRawLocalizedDescription(BattleAction battleAction)
	{
		return Smart.Format(base.localizationManager.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription), Smart.Format(base.localizationManager.GetLocalizedDieYouOwn(isTheAmountOf: true), hexDiceTier.GetLocalizedDiceTierWithDie()));
	}
}
